import{_ as a,o as t,c as n,a5 as r}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Two-EC2 AI rebalance implementation plan","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/plans/2026-11-03-two-ec2-ai-rebalance.md","filePath":"superpowers/plans/2026-11-03-two-ec2-ai-rebalance.md"}'),i={name:"superpowers/plans/2026-11-03-two-ec2-ai-rebalance.md"};function o(s,e,l,c,d,p){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="two-ec2-ai-rebalance-implementation-plan" tabindex="-1">Two-EC2 AI rebalance implementation plan <a class="header-anchor" href="#two-ec2-ai-rebalance-implementation-plan" aria-label="Permalink to &quot;Two-EC2 AI rebalance implementation plan&quot;">​</a></h1><p>&gt; <strong>For agentic workers:</strong> Use superpowers:executing-plans to implement this plan task-by-task.</p><p><strong>Goal:</strong> Move the existing AI API/crawler/consumer to the gateway EC2 without adding or resizing EC2 instances.</p><p><strong>Architecture:</strong> Gateway EC2 (172.31.27.199) runs Nginx, gateway and AI; service EC2 (172.31.24.149) retains Business, Publisher, PostgreSQL, Redis, RabbitMQ and ChromaDB. AI has a 5 GiB hard RAM limit and 1.5 CPU limit. Preserve the current immutable AI image, runtime secrets, crawler data and model cache. Increase gateway root EBS from 10 to 20 GiB for the 3.78 GiB image and 1.5 GiB model cache.</p><p><strong>Tech Stack:</strong> Docker Compose JSON, Terraform AWS provider, SSH/SSM, GitHub Actions.</p><p><strong>Spec:</strong> User selected the proposed reuse of the two existing machines in this chat.</p><h2 id="global-constraints" tabindex="-1">Global constraints <a class="header-anchor" href="#global-constraints" aria-label="Permalink to &quot;Global constraints&quot;">​</a></h2><ul><li>No EC2 replacement, no database volume removal, no duplicate active scheduler.</li><li>Secrets remain in mode-0600 runtime env files and travel only over encrypted transport.</li><li>TCP 8082: service SG to gateway SG; TCP 5672/8000: gateway SG to service SG. Bind published ports to private addresses only; reuse existing Redis rule.</li><li>Preserve running image tags when changing live manifests; repository baseline tags are not deployment inputs.</li><li>Keep old AI container/volume and manifest/env backups for rollback; do not remove volumes.</li></ul><h2 id="review-focus" tabindex="-1">Review focus <a class="header-anchor" href="#review-focus" aria-label="Permalink to &quot;Review focus&quot;">​</a></h2><ul><li>Cross-host dependencies must use reachable private endpoints, including REDIS_URL.</li><li>Crawler files outside the data volume and model cache must be checked before cutover.</li><li>Starting a second AI instance before stopping the old scheduler is forbidden.</li><li>CI must deploy AI to the new host/manifest and serialize updates on that host.</li><li>Health checks are necessary but cannot prove the original crawl OOM resolved; verify a bounded actual crawl separately.</li></ul><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><ul><li>[x] Inspect live image, mounts, endpoint variable names and disk capacity; snapshot current manifests and env files remotely.</li><li>[x] Move AI definition/data volume to backend.compose.json, add persistent model cache, set cross-host dependencies and limits; publish RabbitMQ/Chroma on service private IP and update Business AI URL.</li><li>[x] Add only three SG ingress rules and configure gateway root volume at 20 GiB in Terraform; inspect plan for replacements/unrelated drift before applying. Plan reviewed and applied after explicit production authorization; final plan reports no changes. Corrected local ignored service disk input from 22 to actual 20 GiB to avoid unrelated growth; gateway input was 8 GiB and is now 20 GiB rather than attempting a shrink from actual 10 GiB.</li><li>[x] Update AI CI target to gateway instance/backend.compose.json and document topology, migration and rollback. Add shared host-level flock to AI and gateway workflows because both mutate the backend manifest.</li><li>[x] Validate JSON, Compose, Terraform and workflow changes; review diff. Compose validation without env resolution, Terraform validate/fmt, placement/network/volume contracts, workflow YAML/lock assertions and Amazon Linux bash -n all passed. Independent review found no remaining actionable issue. Production env/dependency and crawl checks remain pending.</li><li>[x] Stage latest running AI image/cache and manifests on gateway. Stop source AI, transfer consistent data, start destination, verify dependencies and Business connectivity. Recreate only affected services; retain stopped source AI for rollback.</li><li>[x] Verify private port bindings, public HTTPS health, RAM limits and singleton crawler. Remove temporary transfer access. Record any incomplete workload verification. Actual browser smoke passed with zero new OOM/restarts; full authenticated crawl requires user session re-upload. All CI deploy workflows re-enabled after AI/gateway remote workflow updates.</li></ul><h2 id="approval-boundary-discovered-during-preparation" tabindex="-1">Approval boundary discovered during preparation <a class="header-anchor" href="#approval-boundary-discovered-during-preparation" aria-label="Permalink to &quot;Approval boundary discovered during preparation&quot;">​</a></h2><p>User explicitly authorized production changes after disclosure of the maintenance window, RAM-only session loss and irreversible EBS expansion. Applied on 2026-11-03. Full result and remaining authenticated-crawl verification are recorded in <code>prod/ec2-ecr/rebalance-ai.md</code>.</p>',14)])])}const h=a(i,[["render",o]]);export{m as __pageData,h as default};
